//! PG&E Net Billing Tariff (NBT, "NEM 3") export credit values, built in from PG&E's
//! published files so the owner only has to pick their vintage.
//!
//! Source: PG&E "Solar Billing Plan Export Rates" (<https://www.pge.com/eecvalues>), files
//! dated 2024-12-18; calendar year 2026 checked against the June 2026 price sheets
//! (<https://www.pge.com/solarbilling>). `data/pge_nbt.json` is generated by
//! `tools/gen_pge_nbt.py`. ACC Plus amounts are from Schedule NBT, section D.
//!
//! The export credit for an hour is generation + delivery for the customer's vintage
//! (calendar year of the completed interconnection application), the calendar year, the
//! month, weekday or weekend/holiday, and the local hour. Generation applies only while PG&E
//! supplies the customer's generation (not with a community choice aggregator, CCA).

use std::collections::BTreeMap;
use std::sync::LazyLock;

use chrono::{Datelike, NaiveDate};
use serde::Deserialize;

const RAW: &str = include_str!("../data/pge_nbt.json");

/// Matrices in 1/100000 $/kWh, `[month 0..12][hour 0..24]`.
#[derive(Clone, Deserialize)]
struct YearTable {
    g_wd: Vec<Vec<i64>>,
    g_we: Vec<Vec<i64>>,
    d_wd: Vec<Vec<i64>>,
    d_we: Vec<Vec<i64>>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum VintageEntry {
    /// Same values as another vintage.
    Alias(String),
    Years(BTreeMap<String, YearTable>),
}

#[derive(Deserialize)]
struct Doc {
    vintages: BTreeMap<String, VintageEntry>,
}

static DATA: LazyLock<BTreeMap<i32, BTreeMap<i32, YearTable>>> = LazyLock::new(|| {
    let doc: Doc = serde_json::from_str(RAW).expect("built-in PG&E NBT table is valid JSON");
    let mut tables: BTreeMap<String, BTreeMap<i32, YearTable>> = BTreeMap::new();
    let num = |y: BTreeMap<String, YearTable>| -> BTreeMap<i32, YearTable> {
        y.into_iter()
            .map(|(k, v)| (k.parse().expect("calendar year"), v))
            .collect()
    };
    let mut aliases = Vec::new();
    for (v, e) in doc.vintages {
        match e {
            VintageEntry::Years(y) => {
                tables.insert(v, num(y));
            }
            VintageEntry::Alias(to) => aliases.push((v, to)),
        }
    }
    let mut out = BTreeMap::new();
    for (v, to) in aliases {
        if let Some(y) = tables.get(&to) {
            out.insert(v.parse().expect("vintage year"), y.clone());
        }
    }
    for (v, y) in tables {
        out.insert(v.parse().expect("vintage year"), y);
    }
    out
});

/// Vintages with built-in values.
pub fn vintages() -> Vec<i32> {
    DATA.keys().copied().collect()
}

/// Calendar years available for a vintage.
pub fn years(vintage: i32) -> Vec<i32> {
    DATA.get(&vintage)
        .map(|y| y.keys().copied().collect())
        .unwrap_or_default()
}

/// Residential (non-low-income) ACC Plus adder by interconnection application year,
/// $/kWh, from Schedule NBT section D. Constant for 9 years from PTO.
pub fn acc_plus_residential(vintage: i32) -> Option<f64> {
    match vintage {
        2023 => Some(0.0220),
        2024 => Some(0.0176),
        2025 => Some(0.0132),
        2026 => Some(0.0088),
        2027 => Some(0.0044),
        _ => None,
    }
}

/// Export credit parts for one hour, $/kWh.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Credit {
    pub generation: f64,
    pub delivery: f64,
    /// The calendar year whose values were used (the nearest available if `date`'s year is
    /// outside the built-in range).
    pub year_used: i32,
}

/// Export credit for a local date and hour (0–23, Pacific prevailing time).
pub fn credit(
    vintage: i32,
    date: NaiveDate,
    hour: u32,
    weekend_or_holiday: bool,
) -> Option<Credit> {
    let years = DATA.get(&vintage)?;
    let y = date.year();
    let (&year_used, t) = years
        .range(..=y)
        .next_back()
        .or_else(|| years.iter().next())?;
    let (m, h) = (date.month0() as usize, hour.min(23) as usize);
    let (g, d) = if weekend_or_holiday {
        (&t.g_we, &t.d_we)
    } else {
        (&t.g_wd, &t.d_wd)
    };
    // Each component is floored at $0 (Schedule NBT).
    let cell = |x: &Vec<Vec<i64>>| {
        x.get(m)
            .and_then(|r| r.get(h))
            .map(|v| (*v as f64 / 100000.0).max(0.0))
    };
    Some(Credit {
        generation: cell(g)?,
        delivery: cell(d)?,
        year_used,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn d(y: i32, m: u32, day: u32) -> NaiveDate {
        NaiveDate::from_ymd_opt(y, m, day).unwrap()
    }

    #[test]
    fn matches_pge_price_sheet() {
        assert_eq!(vintages(), vec![2023, 2024, 2025, 2026]);
        // 2026 price sheet, vintage 2024, September weekday 7 pm: 2.45454 + 0.06685.
        let c = credit(2024, d(2026, 9, 15), 19, false).unwrap();
        assert!(
            (c.generation - 2.45454).abs() < 1e-9 && (c.delivery - 0.06685).abs() < 1e-9,
            "{c:?}"
        );
        assert_eq!(c.year_used, 2026);
        // Vintage 2024, January weekday midnight total 0.0595; vintage 2025 0.09431.
        let t = |v, date, h, we| {
            let c = credit(v, date, h, we).unwrap();
            ((c.generation + c.delivery) * 100000.0).round() / 100000.0
        };
        assert_eq!(t(2024, d(2026, 1, 6), 0, false), 0.0595);
        assert_eq!(t(2025, d(2026, 1, 6), 0, false), 0.09431);
        // Weekend table, vintage 2024, July 7 pm: 0.80735.
        assert_eq!(t(2024, d(2026, 7, 4), 19, true), 0.80735);
        // Vintage 2023 has the same values as 2024.
        assert_eq!(t(2023, d(2026, 9, 15), 19, false), 2.52139);
    }

    #[test]
    fn years_outside_the_table_use_the_nearest() {
        assert_eq!(
            credit(2026, d(2025, 6, 2), 12, false).unwrap().year_used,
            2026
        );
        assert_eq!(
            credit(2024, d(2050, 6, 2), 12, false).unwrap().year_used,
            2036
        );
        assert!(credit(2019, d(2026, 6, 2), 12, false).is_none());
        assert_eq!(acc_plus_residential(2024), Some(0.0176));
    }
}

/// PG&E time-of-use holidays (New Year's, Presidents Day, Memorial Day, Independence Day,
/// Labor Day, Veterans Day, Thanksgiving, Christmas) on the dates they are legally observed:
/// a Saturday holiday moves to Friday, a Sunday holiday to Monday. Matches the day types in
/// PG&E's export-rate files.
pub fn is_pge_holiday(d: NaiveDate) -> bool {
    use chrono::Weekday;
    let y = d.year();
    let nth = |m: u32, wd: Weekday, n: u8| NaiveDate::from_weekday_of_month_opt(y, m, wd, n);
    let last_monday_may = (1..=5).rev().find_map(|n| nth(5, Weekday::Mon, n));
    let observed = |m: u32, day: u32, year: i32| {
        NaiveDate::from_ymd_opt(year, m, day).map(|x| match x.weekday() {
            Weekday::Sat => x.pred_opt().unwrap_or(x),
            Weekday::Sun => x.succ_opt().unwrap_or(x),
            _ => x,
        })
    };
    let fixed = [
        observed(1, 1, y),
        observed(1, 1, y + 1), // New Year's Day on a Saturday is observed on Dec 31
        observed(7, 4, y),
        observed(11, 11, y),
        observed(12, 25, y),
    ];
    let floating = [
        nth(2, Weekday::Mon, 3),
        last_monday_may,
        nth(9, Weekday::Mon, 1),
        nth(11, Weekday::Thu, 4),
    ];
    fixed.iter().chain(floating.iter()).any(|x| *x == Some(d))
}

#[cfg(test)]
mod holiday_tests {
    use super::*;

    #[test]
    fn observed_holidays_match_pge_files() {
        let d = |y, m, day| NaiveDate::from_ymd_opt(y, m, day).unwrap();
        for x in [
            d(2026, 1, 1),
            d(2026, 2, 16),
            d(2026, 5, 25),
            d(2026, 7, 3),
            d(2026, 9, 7),
            d(2026, 11, 11),
            d(2026, 11, 26),
            d(2026, 12, 25),
            d(2027, 7, 5),
            d(2027, 12, 24),
            d(2027, 12, 31),
            d(2027, 5, 31),
        ] {
            assert!(is_pge_holiday(x), "{x}");
        }
        for x in [d(2026, 7, 4), d(2026, 7, 6), d(2027, 7, 4), d(2026, 12, 24)] {
            assert!(!is_pge_holiday(x), "{x}");
        }
    }
}

/// `[month][hour]` prices in $/kWh.
pub type Grid = Vec<Vec<f64>>;

/// A whole year's export credits (weekday and weekend/holiday, `[month][hour]`, $/kWh)
/// for previewing in the dashboard. Returns the calendar year actually used.
pub fn table(vintage: i32, year: i32, generation: bool) -> Option<(i32, Grid, Grid)> {
    let mut used = year;
    let mut grid = |weekend: bool| -> Option<Vec<Vec<f64>>> {
        (1..=12u32)
            .map(|m| {
                let date = NaiveDate::from_ymd_opt(year, m, 1)?;
                (0..24u32)
                    .map(|h| {
                        let c = credit(vintage, date, h, weekend)?;
                        used = c.year_used;
                        Some(c.delivery + if generation { c.generation } else { 0.0 })
                    })
                    .collect()
            })
            .collect()
    };
    let wd = grid(false)?;
    let we = grid(true)?;
    Some((used, wd, we))
}
